insert into public.events (id, slug, branch_id, resource_id, title, title_ar,
  description, description_ar, time_range, capacity, status, is_public,
  is_members_only, requires_registration)
select v.id::uuid, v.slug, b.id, r.id, v.title, v.title_ar, v.body, v.body_ar,
       tstzrange(
         ((v.day::date + (v.starth || ':00')::time) at time zone 'Asia/Riyadh'),
         ((v.day::date + (v.endh   || ':00')::time) at time zone 'Asia/Riyadh'),
         '[)'),
       v.cap::int, v.status, v.pub::boolean, not v.pub::boolean, true
from (values
  ('e2000000-0000-4000-8000-000000000001', 'demo-event-1', 'Founders Breakfast', 'فطور المؤسسين', 'A monthly breakfast for founders on the floor.', 'فطور شهري لمؤسسي الشركات في الطابق.', '2026-07-13', 18, 20, 'completed', true, 20),
  ('e2000000-0000-4000-8000-000000000002', 'demo-event-2', 'Arabic UX Meetup', 'ملتقى تجربة المستخدم العربية', 'Designing interfaces that read right in Arabic.', 'تصميم واجهات تُقرأ بشكل صحيح بالعربية.', '2026-08-08', 18, 20, 'completed', true, 20),
  ('e2000000-0000-4000-8000-000000000003', 'demo-event-3', 'VAT & ZATCA Clinic', 'عيادة الضريبة والفوترة', 'Practical session on e-invoicing compliance.', 'جلسة عملية حول الامتثال للفوترة الإلكترونية.', '2026-08-26', 18, 20, 'scheduled', true, 20),
  ('e2000000-0000-4000-8000-000000000004', 'demo-event-4', 'Investor Office Hours', 'ساعات مكتب المستثمرين', 'Fifteen-minute slots with visiting investors.', 'مواعيد قصيرة مع مستثمرين زائرين.', '2026-09-09', 18, 20, 'scheduled', true, 20),
  ('e2000000-0000-4000-8000-000000000005', 'demo-event-5', 'Ramadan Iftar', 'إفطار رمضان', 'Floor-wide iftar in the Majlis.', 'إفطار جماعي في المجلس.', '2026-09-30', 18, 20, 'scheduled', true, 20),
  ('e2000000-0000-4000-8000-000000000006', 'demo-event-6', 'Quarterly Town Hall', 'اللقاء الفصلي', 'Mars Space updates for all members.', 'تحديثات مارس سبيس لجميع الأعضاء.', '2026-10-21', 18, 20, 'scheduled', true, 20)
) as v(id, slug, title, title_ar, body, body_ar, day, starth, endh, status, pub, cap)
join public.resources r on r.category = 'community_hall' and r.status = 'available'
cross join (select id from public.branches where slug = 'jeddah') b;

